/* Online classroom UI. All persisted writes go through authenticated Firebase. */
(() => {
'use strict';
const KEY='webgame_classroom_v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const clone=x=>JSON.parse(JSON.stringify(x));
const icons={arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',book:'<path d="M12 6v15m0-15C9 3 5 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-7-1-10 2Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',check:'<path d="m5 12 4 4L19 6"/>',message:'<path d="M21 15a3 3 0 0 1-3 3H8l-5 4V5a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3Z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3" fill="currentColor"/><circle cx="16" cy="17" r="3" fill="currentColor"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',play:'<path d="m9 5 11 7-11 7Z"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>'};
const icon=n=>`<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const defaults=()=>({schema:1,course:clone(window.COURSE_DEFAULTS),slides:clone(window.SLIDE_DEFAULTS),policies:{locked:false,pdf:true,materials:true,gate:false,questions:true,reviews:true},live:{slide:0,timerEnd:0,timerPaused:0},questions:[],reviews:[],enrollments:[],answers:{},updated:Date.now()});
const cloud=window.ClassroomCloud;
let state=defaults(), personId='',cloudStatus={teacher:false,ready:false,connected:false};
const isTeacher=()=>cloudStatus.teacher===true;
const dirtyFields=new Map();let draftRevision=0;
const draftKey=el=>{const form=el.closest('form');return form&&el.id?form.id+':'+(form.dataset.slideId||'')+':'+el.id:null;};
function captureDrafts(){for(const el of document.querySelectorAll('input,textarea,select')){const key=draftKey(el),old=key&&dirtyFields.get(key);if(old){old.value=el.value;old.start=el.selectionStart;old.end=el.selectionEnd;}}}
function markDirty(e){const el=e.target;if(!el.matches('input:not([type=file]):not([type=checkbox]),textarea,select'))return;const key=draftKey(el);if(key)dirtyFields.set(key,{value:el.value,start:el.selectionStart,end:el.selectionEnd,revision:++draftRevision});}
document.addEventListener('input',markDirty);document.addEventListener('change',markDirty);
function restoreDrafts(){for(const el of document.querySelectorAll('input,textarea,select')){const saved=dirtyFields.get(draftKey(el));if(!saved||el.disabled)continue;el.value=saved.value;if(typeof saved.start==='number'&&el.setSelectionRange)try{el.setSelectionRange(saved.start,saved.end);}catch{}}}

const safe=fn=>async(...args)=>{try{return await fn(...args);}catch(e){toast('저장/연결 실패: '+(e.message||e));}};
let route=(location.hash.replace('#','').split('/')[0]||'home');
if(!['home','slides','participate','resources','admin'].includes(route))route='home';
let localSlide=0,follow=true,moduleFilter='all',adminTab='control',participationTab='questions',modalLastFocus=null,toastTimeout;
const currentSlide=()=>Math.min(state.slides.length-1,Math.max(0,localSlide));
const teacherSlide=()=>Math.min(state.slides.length-1,Math.max(0,state.live.slide||0));
const moduleOf=s=>state.course.modules.find(m=>m.id===s.module)||state.course.modules[0];
const countPending=()=>state.enrollments.filter(e=>!e.approved).length+state.reviews.filter(r=>!r.approved).length;
const myEnrollment=()=>state.enrollments.find(e=>e.person===personId);
async function updateStore(fn,redraw=true){if(!cloud)throw Error('온라인 연결을 사용할 수 없습니다.');const before=clone(state),next=clone(state);fn(next);await cloud.commit(before,next);state=cloud.snapshot();if(state.policies.locked||follow)localSlide=teacherSlide();if(redraw)render();}
function toast(text){const t=$('#toast');t.textContent=text;t.hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.hidden=true,3200);}
const timeText=t=>new Date(t).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});
const byNew=a=>[...a].sort((a,b)=>b.created-a.created);
function setRoute(r){if(r==='slides'&&follow&&state.policies.locked)localSlide=teacherSlide();if(location.hash==='#'+r){route=r;render();}else location.hash=r;}
function render(){
 captureDrafts();const focusedDraft=document.activeElement?.id;const editedSlide=$('#slide-form')?.dataset.slideId;
 $('#remote-update-note')?.remove();
 if(state.policies.locked)localSlide=teacherSlide();
 document.body.hidden=false; document.querySelectorAll('button[data-route=admin]').forEach(el=>el.hidden=!isTeacher());
 renderCloudStatus();
 document.body.dataset.route=route;
 document.title=`${state.course.title} · WEB GAME CLASS`;
 document.querySelectorAll('button[data-route],a[data-route]').forEach(b=>{b.classList.toggle('active',b.dataset.route===route);b.setAttribute('aria-current',b.dataset.route===route?'page':'false');});
 const root=$('#main');root.innerHTML=({home:homePage,slides:slidesPage,participate:participatePage,resources:resourcesPage,admin:adminPage}[route]||homePage)();
 $('#print-root').innerHTML=state.policies.pdf?state.slides.map((s,i)=>`<section class="print-slide">${stageMarkup(s,i,true)}</section>`).join(''):'';
 if(editedSlide&&$('#edit-slide-select')){const i=state.slides.findIndex(s=>s.id===editedSlide);if(i>=0){$('#edit-slide-select').value=String(i);$('#slide-edit-form-slot').innerHTML=slideEditor(i);}}
 restoreDrafts();if(focusedDraft)document.getElementById(focusedDraft)?.focus({preventScroll:true});
 tickTimers();
}
function pageHeading(kicker,title,subtitle,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1><p class="lead">${esc(subtitle)}</p></div>${actions}</div>`;}
const localNotice=()=>'<div class="local-banner"><span>온라인 수업 · 질문은 참여자에게 공유됩니다. 신청 이름과 퀴즈 답안은 본인과 강사만, 후기는 승인 뒤 공개됩니다. 연결 오류 시 새 기록은 저장되지 않습니다.</span></div>';
function renderCloudStatus(){let bar=$('#cloud-status');if(!bar){bar=document.createElement('div');bar.id='cloud-status';bar.className='cloud-status';document.body.prepend(bar);}bar.innerHTML='<span role="status">'+(cloudStatus.connected?'서버 연결됨':'서버 연결 안 됨')+' · '+(isTeacher()?'강사 인증 완료':cloudStatus.ready?'수강생 인증 완료':'인증 대기 / 읽기 전용')+'</span><button class="btn ghost small" data-action="'+(isTeacher()?'teacher-logout':'teacher-login')+'">'+(isTeacher()?'강사 로그아웃':'강사 Google 로그인')+'</button>';}
function homePage(){const c=state.course;return `<div class="shell">
<div class="hero-grid"><section class="hero-panel"><div class="tag-row"><span class="pill">만들며 배우는 코딩 수업</span><span class="eyebrow">IMAGINE. MAKE. PLAY.</span></div><h1>${esc(c.title)}</h1><p class="hero-description">${esc(c.subtitle)}</p><p>${esc(c.description)}</p><div class="button-row"><button class="btn dark" data-route="slides">수업 시작하기 ${icon('arrow')}</button><button class="btn ghost" data-route="resources">실습 자료 보기</button></div><div class="hero-footer"><span>${icon('clock')} ${esc(c.duration)}</span><span>${esc(c.instructor)}</span><span>${esc(c.date)}</span></div></section>
<aside class="today-card"><div class="card-label"><span>YOUR LEARNING PATH</span><span class="chip">${c.modules.length}개 차시</span></div><h2 class="today-title">아이디어에서<br>나만의 게임까지.</h2><ol class="session-list">${c.modules.map((m,i)=>`<li><span class="session-dot">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(m.title)}</strong><small>${esc(m.summary)}</small></div><span class="session-time">${m.minutes}분</span></li>`).join('')}</ol><p class="muted">${esc(c.audience)}</p></aside></div>
${localNotice()}
${gameSection()}
<div class="stat-grid"><div class="stat-card"><strong>${state.slides.length}<small>장</small></strong><span>웹슬라이드</span></div><div class="stat-card"><strong>${c.modules.length}<small>개</small></strong><span>학습 차시</span></div><div class="stat-card"><strong>1<small>개</small></strong><span>직접 만드는 웹게임</span></div><div class="stat-card"><strong>155<small>분</small></strong><span>수업 135분 + 쉬는 시간 20분</span></div></div>
<section><div class="section-heading"><div><p class="section-label">CURRICULUM</p><h2>첫 게임부터 나만의 게임까지.</h2></div><button class="btn ghost small" data-route="slides">전체 슬라이드 ${icon('arrow')}</button></div><div class="curriculum-grid">${c.modules.map((m,i)=>`<button class="module-card" data-module-start="${esc(m.id)}"><span class="module-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(m.title)}</h3><p>${esc(m.summary)}</p><div class="module-meta"><span>${m.minutes}분 · ${state.slides.filter(s=>s.module===m.id).length}장</span>${icon('arrow')}</div></button>`).join('')}</div></section>
<section class="portal-grid"><div class="panel"><p class="section-label">ONE LINK, ONE CLASSROOM</p><h2>듣고, 따라 하고,<br>질문하는 수업.</h2><p class="muted">강의 안내에서 슬라이드, 실습 자료, 질문과 후기까지.<br>여러 링크를 헤매지 않는 작은 학습 공간입니다.</p><div class="button-row"><button class="btn primary" data-route="participate">수업 참여하기 ${icon('message')}</button></div></div><div class="panel"><p class="section-label">AFTER CLASS</p><h2>수강 후기</h2>${publicReviews(2)}<button class="btn ghost small" data-route="participate">후기 남기기 ${icon('arrow')}</button></div></section>
</div>`;}
function stageMarkup(s,index,print=false){const mod=moduleOf(s);let content='';
 if(s.kind==='prompt')content=`<div class="prompt-code">${esc(s.prompt||'')}</div>${print?'':`<button class="btn dark small" data-copy-slide="${index}">${icon('copy')} 프롬프트 복사</button>`}`;
 else if(s.kind==='quiz'){const mine=state.answers[s.id]?.[personId];content=`<div class="quiz-options">${(s.options||[]).map((o,i)=>`<button class="quiz-option ${mine===i?'selected':''} ${mine!==undefined&&i===s.answer?'correct':''}" data-answer-slide="${index}" data-answer="${i}" ${print?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div>${mine!==undefined?`<p class="quiz-feedback">${mine===s.answer?'정답입니다.':'다시 생각해보세요.'} · ${esc(s.items?.find(it=>it.title==='정답 확인')?.body||s.items?.[0]?.body||'응답이 저장되었습니다.')}</p>`:'<p class="muted quiz-feedback">선택하면 본인 응답이 서버에 저장됩니다.</p>'}`;}
 else if(s.kind==='practice'||s.kind==='break')content=`<div class="slide-grid">${(s.items||[]).map((it,i)=>slideBox(it,i)).join('')}</div><div class="practice-timer"><span>${s.kind==='break'?'쉬는 시간':'실습 시간'}</span><strong class="timer-display" data-timer>${String(s.minutes||5).padStart(2,'0')}:00</strong>${print||!isTeacher()?'':`<button class="btn dark small" data-start-practice="${s.minutes||5}">타이머 시작</button>`}</div>`;
 else content=`<div class="slide-grid ${s.kind==='compare'?'comparison-grid':''}">${(s.items||[]).map((it,i)=>slideBox(it,i)).join('')}</div>`;
 return `<article class="slide-page ${s.kind==='cover'||s.kind==='ending'?'cover':''} ${s.kind==='prompt'?'prompt-page':''} ${s.kind==='quiz'?'quiz-page':''}" data-kind="${esc(s.kind)}"><div class="slide-kicker"><span>${esc(mod?.title||'강의')}</span><span>WEB GAME / ${String(index+1).padStart(2,'0')}</span></div><div class="slide-content"><h2 class="slide-title">${esc(s.title)}</h2><p class="slide-subtitle">${esc(s.subtitle)}</p>${content}</div><div class="slide-footer"><span>${esc(state.course.title)}</span><span>${String(index+1).padStart(2,'0')} / ${state.slides.length}</span></div></article>`;}

function gameSection(){return `<section class="game-feature"><div><p class="section-label">TODAY’S PROJECT</p><h2>별 하나에서 시작하는<br>나의 첫 웹게임.</h2><p class="muted">30초 안에 움직이는 별을 잡아보세요. 오늘은 이 게임을 AI와 함께 만들고, 규칙과 디자인을 내 방식으로 바꿉니다.</p><div class="button-row"><button class="btn dark" data-action="play-game">완성 게임 미리보기 ${icon('play')}</button><button class="btn ghost" data-action="download-game">게임 HTML 내려받기 ${icon('download')}</button></div><small class="muted">설치 없이 실행 · 오프라인 가능 · 개인정보 입력 없음</small></div><div class="game-poster" aria-hidden="true"><div class="poster-bar"><span>STAR CATCHER</span><span>00:30</span></div><div class="poster-star"><svg viewBox="0 0 100 100" width="90" height="90"><path d="m50 6 13 28 31 4-23 22 6 32-27-15-27 15 6-32L6 38l31-4Z" fill="#e8b62c" stroke="#191a18" stroke-width="4"/></svg></div><div class="poster-base"><strong>별 잡기</strong><span>CLICK. CATCH. CREATE.</span></div></div></section>`;}
function playGame(){showModal('완성 게임 미리보기', '<iframe id="game-demo-frame" class="game-demo-frame" title="별 잡기 실습 게임" sandbox="allow-scripts allow-same-origin"></iframe>');$('#game-demo-frame').srcdoc=window.WEBGAME_DEMO_HTML||'<p>게임 파일을 불러오지 못했습니다.</p>';}

function slideBox(it,i){return `<div class="slide-box"><span class="slide-box-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(it.title)}</h3><p>${esc(it.body)}</p></div></div>`;}
function slidesPage(){const s=state.slides[currentSlide()];const gated=!isTeacher()&&state.policies.gate&&!myEnrollment()?.approved;
 return `<div class="shell slides-workspace">${pageHeading('WEB SLIDES','생각을 게임으로 만드는 시간.',`${state.course.title} · ${state.slides.length}장의 웹슬라이드`)}<div class="slide-toolbar"><div class="slide-meta"><span class="chip">${state.policies.locked?'강사 진행 중':'자유롭게 둘러보기'}</span><label class="check-row"><input id="follow-toggle" type="checkbox" ${follow||state.policies.locked?'checked':''} ${state.policies.locked?'disabled':''}>강사 따라가기</label><span class="muted">실시간 온라인 연결</span></div><div class="button-row"><button class="btn ghost small" data-action="grid">${icon('grid')} 목차 <kbd>G</kbd></button><button class="btn ghost small" data-action="print" ${state.policies.pdf?'':'disabled'}>${icon('download')} PDF</button><button class="btn ghost small" data-action="fullscreen" aria-label="슬라이드 전체화면">${icon('expand')}</button></div></div>
${gated?`<div class="panel gate-panel"><h2>수강 승인을 기다리고 있어요.</h2><p>수업 참여에서 신청하면 강사가 승인합니다.</p><button class="btn primary" data-action="enroll">수강 신청</button><p class="muted">수강 승인 화면 정책입니다. 공개 슬라이드와 소스를 복제 방지하는 DRM은 아닙니다.</p></div>`:`<div id="slide-stage" class="slide-stage">${stageMarkup(s,currentSlide())}</div>`}
<div class="slide-controls"><button class="btn ghost" data-action="prev" ${currentSlide()===0||state.policies.locked?'disabled':''}>← 이전</button><div class="slide-nav"><span><strong>${currentSlide()+1}</strong> / ${state.slides.length}</span><div class="progress-track"><div class="progress-fill" style="width:${(currentSlide()+1)/state.slides.length*100}%"></div></div><small>${state.policies.locked?'강사가 이동하면 함께 이동합니다.':'방향키 ← →로 이동할 수 있어요.'}</small></div><button class="btn dark" data-action="next" ${currentSlide()===state.slides.length-1||state.policies.locked?'disabled':''}>다음 →</button></div>
<div class="slide-outline">${state.course.modules.map(m=>`<button class="outline-btn ${s.module===m.id?'active':''}" data-module-start="${esc(m.id)}" ${state.policies.locked?'disabled':''}>${esc(m.title)}</button>`).join('')}</div><div class="notice">${icon('book')}<span>수업 중 막히는 부분은 <button class="text-button" data-route="participate">질문 대기열</button>에 남겨주세요. 내용은 관리자에서 내 강의에 맞게 바꿀 수 있습니다.</span></div></div>`;}
function publicReviews(limit=99){const reviews=byNew(state.publicReviews||[]).slice(0,limit);return reviews.length?`<div class="review-grid">${reviews.map(r=>`<article class="review-card"><div class="stars" aria-label="5점 만점에 ${r.rating}점">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><p>${esc(r.text)}</p><small>익명 수강생 · 승인된 후기</small></article>`).join('')}</div>`:`<div class="empty"><p>아직 공개된 후기가 없어요.</p><small>후기는 이름 없이, 강사 승인 뒤에만 공개됩니다.</small></div>`;}
function participatePage(){const me=myEnrollment();return `<div class="shell">${pageHeading('PARTICIPATE','혼자 듣지 않는 수업.','질문하고, 결과를 나누고, 오늘의 배움을 남겨보세요.',`<button class="btn ghost" data-action="enroll">${me?(me.approved?'수강 승인 완료':'신청 확인'):'수강 신청'}</button>`)}${localNotice()}<div class="tab-bar" role="tablist">${[['questions','질문 대기열'],['reviews','수강 후기'],['quiz','퀴즈 현황']].map(([k,v])=>`<button role="tab" aria-selected="${participationTab===k}" class="${participationTab===k?'active':''}" data-part-tab="${k}">${v}</button>`).join('')}</div>${participationTab==='questions'?questionsPanel():participationTab==='reviews'?reviewsPanel():quizPanel(false)}</div>`;}
function questionsPanel(){if(!isTeacher()&&state.policies.gate&&!myEnrollment()?.approved)return '<section class="panel"><p>질문을 보거나 작성하려면 수강 승인이 필요합니다.</p><button class="btn dark" data-action="enroll">수강 신청</button></section>';return `<div class="portal-grid"><section class="panel"><p class="section-label">ASK A QUESTION</p><h2>질문을 남겨주세요.</h2><p class="muted">실명 없이 질문만 공유됩니다. 비밀번호·개인정보는 쓰지 마세요.</p>${state.policies.questions?`<form id="question-form" class="stack"><div class="field"><label for="question-text">궁금한 내용</label><textarea id="question-text" name="text" rows="5" maxlength="600" placeholder="어느 부분에서 막혔는지 구체적으로 적어주세요." required></textarea></div><button class="btn dark" type="submit">질문 등록 ${icon('arrow')}</button></form>`:'<div class="notice">지금은 질문 접수가 닫혀 있습니다.</div>'}</section><section class="panel"><div class="panel-title"><h2>함께 궁금한 질문</h2><span class="count">${state.questions.length}</span></div>${questionList(false)}</section></div>`;}
function questionList(admin){const q=[...state.questions].sort((a,b)=>Number(a.done)-Number(b.done)||b.voters.length-a.voters.length||a.created-b.created);return q.length?`<div class="stack">${q.map((x,i)=>`<article class="queue-item"><div class="list-content"><span class="badge ${x.done?'approved':'pending'}">${x.done?'답변 완료':'답변 대기'}</span><p>${esc(x.text)}</p><small class="muted">${timeText(x.created)} · 익명 질문</small></div><div class="list-actions">${admin?`<button class="btn ghost small" data-question-done="${esc(x.id)}">${x.done?'다시 대기':'답변 완료'}</button><button class="btn ghost small danger" data-question-delete="${esc(x.id)}">삭제</button>`:`<button class="btn ghost small" data-question-vote="${esc(x.id)}" ${x.voters.includes(personId)?'disabled':''}>공감 ${x.voters.length}</button>`}</div></article>`).join('')}</div>`:'<div class="empty"><p>첫 번째 질문을 기다리고 있어요.</p><small>궁금한 부분을 편하게 남겨주세요.</small></div>';}
function reviewsPanel(){if(!isTeacher()&&state.policies.gate&&!myEnrollment()?.approved)return '<section class="panel"><p>후기를 작성하려면 수강 승인이 필요합니다.</p><button class="btn dark" data-action="enroll">수강 신청</button>'+publicReviews()+'</section>';const mine=state.reviews.find(r=>r.person===personId);return `<div class="portal-grid"><section class="panel"><p class="section-label">REFLECT & SHARE</p><h2>오늘 수업은 어땠나요?</h2><p class="muted">공개할 때 이름은 표시하지 않습니다. 승인된 후기를 수정하면 다시 비공개로 바뀝니다.</p>${state.policies.reviews?`<form id="review-form" class="stack"><div class="field"><label for="review-rating">만족도</label><select id="review-rating" name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}" ${mine?.rating===n?'selected':''}>${n}점 · ${['','아쉬워요','조금 아쉬워요','보통이에요','좋았어요','아주 좋았어요'][n]}</option>`).join('')}</select></div><div class="field"><label for="review-text">후기 한 줄</label><textarea id="review-text" name="text" rows="4" maxlength="500" placeholder="오늘 가져가는 한 가지를 적어주세요." required>${esc(mine?.text||'')}</textarea></div><button class="btn dark" type="submit">${mine?'후기 수정':'후기 제출'} ${icon('arrow')}</button>${mine?`<small class="muted">내 후기 상태: ${mine.approved?'공개 승인됨':'승인 대기 · 비공개'}</small>`:''}</form>`:'<div class="notice">지금은 후기 접수가 닫혀 있습니다.</div>'}</section><section class="panel"><h2>수강생의 한마디</h2>${publicReviews()}</section></div>`;}
function quizPanel(admin){const quiz=state.slides.filter(s=>s.kind==='quiz');return `<div class="stack">${quiz.map(s=>{const answers=Object.values(state.answers[s.id]||{});const right=answers.filter(a=>a===s.answer).length;return `<section class="panel"><div class="panel-title"><h2>${esc(s.title)}</h2><span class="chip">${isTeacher()?'전체 응답 집계':'내 응답만 표시'}</span></div><p>${esc(s.subtitle)}</p><div class="stat-grid"><div class="stat-card"><strong>${answers.length}<small>명</small></strong><span>응답</span></div><div class="stat-card"><strong>${right}<small>명</small></strong><span>정답</span></div><div class="stat-card"><strong>${answers.length?Math.round(right/answers.length*100):0}<small>%</small></strong><span>정답률</span></div></div>${s.options.map((o,i)=>`<div class="quiz-result-row"><span>${String.fromCharCode(65+i)}. ${esc(o)}</span><div class="progress-track"><div class="progress-fill" style="width:${answers.length?answers.filter(a=>a===i).length/answers.length*100:0}%"></div></div><strong>${answers.filter(a=>a===i).length}</strong></div>`).join('')}<button class="btn ghost small" data-go-slide="${state.slides.indexOf(s)}">퀴즈 슬라이드 열기 ${icon('arrow')}</button></section>`;}).join('')||'<div class="empty">퀴즈 슬라이드가 없습니다.</div>'}<p class="muted">수강생에게는 본인 응답만, 강사에게는 전체 집계가 표시됩니다. 퀴즈 정답은 학습용 공개 콘텐츠입니다.</p></div>`;}
function resourcesPage(){const c=state.course;return `<div class="shell">${pageHeading('RESOURCE LIBRARY','필요한 자료를, 한곳에서.','같은 원본에서 꺼내 쓰는 실습 도구와 복사용 프롬프트')}<div class="notice">${icon('book')}<span>이 수업을 위해 새로 작성한 게임 제작 자료입니다. 이름·사진·계정 정보는 입력하지 마세요.</span></div>${state.policies.materials?`<div class="resource-grid">${c.resources.map((r,i)=>`<article class="resource-card"><span class="module-number">${String(i+1).padStart(2,'0')}</span><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><button class="btn ghost small" data-resource="${esc(r.type)}">${icon('download')} TXT 내려받기</button></article>`).join('')}</div><section class="panel"><div class="section-heading"><div><p class="section-label">COPY & START</p><h2>바로 쓰는 프롬프트</h2></div></div><div class="stack">${state.slides.map((s,i)=>s.kind==='prompt'?`<details class="prompt-details"><summary>${esc(s.title)}</summary><pre>${esc(s.prompt)}</pre><button class="btn dark small" data-copy-slide="${i}">${icon('copy')} 복사</button></details>`:'').join('')}</div></section>`:'<div class="panel empty"><h2>자료는 아직 공개 전이에요.</h2><p>강사가 자료를 공개하면 이곳에서 볼 수 있습니다.</p></div>'}<section class="panel glossary"><p class="section-label">SMALL DICTIONARY</p><h2>낯선 용어, 쉽게 이해하기.</h2><div class="curriculum-grid">${c.glossary.map(g=>`<article><h3>${esc(g.term)}</h3><p class="muted">${esc(g.definition)}</p></article>`).join('')}</div></section></div>`;}
function adminPage(){if(!isTeacher())return `<div class="shell"><section class="panel"><h1>강사 인증이 필요합니다.</h1><p>승인된 Google 계정으로 로그인한 강사만 수업을 운영할 수 있습니다.</p><button class="btn dark" data-action="teacher-login">Google로 강사 로그인</button></section></div>`;const tabs=[['control','진행 제어'],['participation','질문 · 퀴즈'],['approval','신청 · 후기 승인'],['edit','강의 편집'],['settings','저장 · 내보내기']];return `<div class="shell">${pageHeading('TEACHER WORKSPACE','수업 운영의 모든 순간.','진행 상태와 자료 공개, 참여 기록을 한눈에 관리하세요.',`<button class="btn dark" data-action="student-window">수강생 창 열기 ${icon('arrow')}</button>`)}${localNotice()}<div class="notice">${icon('lock')}<span><strong>인증된 강사 전용 운영 화면입니다.</strong> 서버 보안 규칙이 강사와 수강생의 접근 권한을 검증합니다.</span></div><div class="admin-layout"><aside class="admin-sidebar"><span class="section-label">WORKSPACE</span><nav class="admin-nav" aria-label="관리자 메뉴">${tabs.map(([k,v])=>`<button class="${adminTab===k?'active':''}" data-admin-tab="${k}">${v}${k==='approval'&&countPending()?`<span class="count">${countPending()}</span>`:''}</button>`).join('')}</nav><div class="admin-sidebar-bottom"><span class="status-dot"></span> Firebase 서버 연결</div></aside><div class="admin-main">${({control:adminControl,participation:()=>`<section class="admin-card"><h2>질문 대기열</h2>${questionList(true)}</section>${quizPanel(true)}`,approval:adminApproval,edit:adminEdit,settings:adminSettings}[adminTab])()}</div></div></div>`;}
function policy(key,title,desc){return `<label class="switch-row"><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span><input class="toggle" type="checkbox" data-policy="${key}" aria-label="${esc(title)}" ${state.policies[key]?'checked':''}></label>`;}
function adminControl(){const s=state.slides[teacherSlide()];return `<div class="admin-grid"><section class="admin-card wide"><div class="admin-card-head"><div><p class="section-label">LIVE CONTROL</p><h2>현재 강의 진행</h2></div><span class="chip">${state.policies.locked?'강사 주도':'자유 열람'}</span></div><div class="admin-kpi"><strong>${String(teacherSlide()+1).padStart(2,'0')}</strong><span>/ ${state.slides.length}</span><div><small>${esc(moduleOf(s)?.title)}</small><h3 class="admin-slide-title">${esc(s.title)}</h3></div></div><div class="button-row"><button class="btn ghost" data-teacher-step="-1" ${teacherSlide()===0?'disabled':''}>← 이전</button><button class="btn dark" data-teacher-step="1" ${teacherSlide()===state.slides.length-1?'disabled':''}>다음 →</button><label class="slide-jump">바로 이동 <select id="teacher-jump" aria-label="강사 슬라이드 바로 이동">${state.slides.map((s,i)=>`<option value="${i}" ${teacherSlide()===i?'selected':''}>${i+1}. ${esc(s.title)}</option>`).join('')}</select></label></div><div class="policy-list">${policy('locked','강사 화면 따라가기 잠금','켜면 수강생 탭은 현재 장을 따라갑니다. 잠금 중에는 임의 이동과 따라가기 해제가 제한됩니다.')}</div></section>
<section class="admin-card"><div class="admin-card-head"><div><p class="section-label">VISIBILITY</p><h2>자료 공개 정책</h2></div>${icon('settings')}</div><div class="policy-list">${policy('pdf','PDF 저장 허용','강사 화면에도 같은 정책을 적용합니다.')}${policy('materials','자료실 공개','프롬프트·실습 자료 다운로드를 표시합니다.')}${policy('gate','수강 승인 흐름 사용','신청 후 강사가 승인합니다. 공개 콘텐츠의 복사 방지 기능은 아닙니다.')}</div></section>
<section class="admin-card"><div class="admin-card-head"><div><p class="section-label">CLASS TIMER</p><h2>공용 실습 타이머</h2></div>${icon('clock')}</div><div class="timer-display" data-timer>05:00</div><div class="button-row"><select id="timer-minutes" aria-label="타이머 분"><option value="3">3분</option><option value="5" selected>5분</option><option value="10">10분</option><option value="15">15분</option></select><button class="btn dark small" data-action="timer-start">시작</button><button class="btn ghost small" data-action="timer-pause">일시정지</button><button class="btn ghost small" data-action="timer-reset">초기화</button></div><p class="muted">탭이 느려져도 실제 종료 시각을 기준으로 남은 시간을 계산합니다.</p></section>
<section class="admin-card"><p class="section-label">PARTICIPATION</p><h2>참여 도구</h2><div class="policy-list">${policy('questions','질문 접수','질문 등록을 열거나 닫습니다.')}${policy('reviews','후기 접수','후기는 제출 후 승인 대기로 저장합니다.')}</div></section><section class="admin-card"><p class="section-label">TODAY’S QUEUE</p><h2>확인이 필요한 항목</h2><div class="stat-grid"><div class="stat-card"><strong>${state.questions.filter(q=>!q.done).length}</strong><span>답변 대기</span></div><div class="stat-card"><strong>${countPending()}</strong><span>승인 대기</span></div></div><button class="btn ghost small" data-admin-tab="approval">신청·후기 확인 ${icon('arrow')}</button></section></div>`;}
function adminApproval(){return `<div class="stack"><section class="admin-card"><div class="panel-title"><h2>수강 신청</h2><span class="count">${state.enrollments.length}</span></div><p class="muted">이름은 이 관리자 목록에서만 표시합니다. 실제 이메일·문자 알림은 보내지 않습니다.</p>${state.enrollments.length?byNew(state.enrollments).map(e=>`<div class="list-item"><div><strong>${esc(e.name)}</strong><small class="muted"> · ${timeText(e.created)}</small><span class="badge ${e.approved?'approved':'pending'}">${e.approved?'승인됨':'승인 대기'}</span></div><button class="btn ghost small" data-enroll-approve="${esc(e.id)}">${e.approved?'승인 취소':'승인'}</button></div>`).join(''):'<div class="empty">신청 내역이 없습니다. 수업 참여에서 신청해보세요.</div>'}</section><section class="admin-card"><h2>후기 공개 승인</h2><p class="muted">기본 비공개 · 건별 승인 · 수정 시 자동 비공개 전환</p>${state.reviews.length?byNew(state.reviews).map(r=>`<article class="queue-item"><div class="list-content"><div class="stars">${'★'.repeat(r.rating)}</div><p>${esc(r.text)}</p><small class="muted">${timeText(r.created)} · 공개 시 이름 없음</small><span class="badge ${r.approved?'approved':'pending'}">${r.approved?'공개 중':'비공개'}</span></div><div class="list-actions"><button class="btn ${r.approved?'ghost':'dark'} small" data-review-approve="${esc(r.id)}">${r.approved?'비공개로':'공개 승인'}</button><button class="btn ghost small danger" data-review-delete="${esc(r.id)}">삭제</button></div></article>`).join(''):'<div class="empty">제출된 후기가 없습니다.</div>'}</section></div>`;}
function adminEdit(){const c=state.course;return `<div class="stack"><section class="admin-card"><p class="section-label">MAKE IT YOURS</p><h2>내 강의 정보</h2><form id="course-form" class="stack"><div class="form-grid">${[['title','강의명',c.title],['subtitle','한 줄 소개',c.subtitle],['instructor','강사명',c.instructor],['date','일정',c.date],['duration','총 강의 시간',c.duration],['audience','수강 대상',c.audience]].map(([k,label,v])=>`<div class="field"><label for="course-${k}">${label}</label><input id="course-${k}" name="${k}" value="${esc(v)}" maxlength="100" required></div>`).join('')}</div><div class="field"><label for="course-description">강의 설명</label><textarea id="course-description" name="description" rows="3" maxlength="500" required>${esc(c.description)}</textarea></div><button class="btn dark" type="submit">강의 정보 저장 ${icon('check')}</button></form></section><section class="admin-card"><div class="admin-card-head"><div><p class="section-label">SLIDE EDITOR</p><h2>슬라이드 내용 바꾸기</h2></div><button class="btn ghost small" data-action="add-slide">새 슬라이드</button></div><div class="field"><label for="edit-slide-select">편집할 슬라이드</label><select id="edit-slide-select">${state.slides.map((s,i)=>`<option value="${i}">${i+1}. ${esc(s.title)}</option>`).join('')}</select></div><div id="slide-edit-form-slot">${slideEditor(0)}</div></section><section class="admin-card"><h2>전체 구조 편집</h2><p class="muted">모듈·자료실·용어집과 슬라이드 유형은 설정에서 강의 JSON을 내려받아 수정한 뒤 가져올 수 있습니다. 가져오기 전에 현재 강의를 백업하세요.</p><button class="btn ghost" data-admin-tab="settings">저장·내보내기 ${icon('arrow')}</button></section></div>`;}
function slideEditor(i){const s=state.slides[i];return `<form id="slide-form" class="stack" data-index="${i}" data-slide-id="${esc(s.id)}"><div class="form-grid"><div class="field"><label for="slide-title">제목</label><input id="slide-title" name="title" value="${esc(s.title)}" maxlength="60" required></div><div class="field"><label for="slide-module">모듈</label><select id="slide-module" name="module">${state.course.modules.map(m=>`<option value="${esc(m.id)}" ${s.module===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select></div></div><div class="field"><label for="slide-subtitle">설명</label><input id="slide-subtitle" name="subtitle" value="${esc(s.subtitle)}" maxlength="130"></div><div class="field"><label for="slide-items">카드 내용 · 한 줄에 제목 | 설명 (최대 4줄)</label><textarea id="slide-items" name="items" rows="5">${esc((s.items||[]).map(it=>it.title+' | '+it.body).join('\n'))}</textarea></div>${s.kind==='prompt'?`<div class="field"><label for="slide-prompt">복사할 프롬프트</label><textarea id="slide-prompt" name="prompt" rows="5" maxlength="1200">${esc(s.prompt)}</textarea></div>`:''}${s.kind==='quiz'?`<div class="field"><label for="slide-options">보기 · 한 줄에 하나 (2~4개)</label><textarea id="slide-options" name="options" rows="4">${esc(s.options.join('\n'))}</textarea></div><div class="field"><label for="slide-answer">정답 번호 (1부터)</label><input id="slide-answer" name="answer" type="number" min="1" max="4" value="${s.answer+1}" required></div>`:''}${['practice','break'].includes(s.kind)?`<div class="field"><label for="slide-minutes">실습 시간 (분)</label><input id="slide-minutes" name="minutes" type="number" min="1" max="60" value="${s.minutes||5}" required></div>`:''}<div class="button-row"><button class="btn dark" type="submit">이 슬라이드 저장</button><button class="btn ghost small" type="button" data-go-slide="${i}">미리보기</button><button class="btn ghost small danger" type="button" data-delete-slide="${i}" ${state.slides.length<2?'disabled':''}>삭제</button></div></form>`;}
function adminSettings(){return `<div class="stack"><section class="admin-card"><p class="section-label">YOUR CONTENT, YOUR FILE</p><h2>저장과 이동</h2><p>강의 내용과 운영 기록은 Firebase 서버에 저장됩니다. 중요한 데이터는 별도로 백업하세요.</p><div class="settings-grid"><div class="panel"><h3>강의 콘텐츠 내보내기</h3><p class="muted">강의 정보와 슬라이드만 포함합니다. 이름·신청·질문·후기는 포함하지 않습니다.</p><button class="btn dark" data-action="export-course">${icon('download')} 강의 JSON</button></div><div class="panel"><h3>강의 콘텐츠 가져오기</h3><p class="muted">강의 JSON 또는 전체 백업을 가져옵니다. 현재 내용은 교체 전 자동 백업합니다.</p><label class="btn ghost" for="import-file">JSON 파일 선택</label><input id="import-file" type="file" accept="application/json,.json" hidden></div></div><div class="button-row"><button class="btn ghost" data-action="export-records">운영 기록 백업</button><button class="btn ghost danger" data-action="reset-records">참여 기록 초기화</button><button class="btn ghost danger" data-action="reset-all">샘플 강의로 초기화</button></div></section><section class="admin-card"><p class="section-label">BEFORE YOU GO LIVE</p><h2>실제 수업 공개 전 확인</h2><ul class="safe-list"><li>강사는 승인된 Google 계정, 수강생은 익명 인증으로 연결됩니다. 불필요한 개인정보를 입력하지 마세요.</li><li>동기화·질문·퀴즈·후기·신청은 같은 온라인 강의실에 실시간 연결됩니다.</li><li>수강생은 본인의 신청·비공개 후기·답안만 읽고 쓸 수 있습니다.</li><li>PDF·자료실 스위치와 수강 승인 게이트는 화면 정책입니다. 공개 파일 복사나 소스 열람을 막는 DRM이 아닙니다.</li><li>이메일·문자 알림은 연결하지 않았으며 비용이 발생하지 않습니다.</li><li>서비스 계정 키·비밀번호·명단을 공개 폴더에 넣지 마세요.</li></ul></section></div>`;}
async function setTeacherSlide(n){await updateStore(s=>s.live.slide=Math.min(s.slides.length-1,Math.max(0,n)));}
function moveSlide(delta){if(state.policies.locked){toast('강사가 현재 슬라이드를 진행하고 있습니다.');return;}follow=false;localSlide=Math.min(state.slides.length-1,Math.max(0,currentSlide()+delta));render();}
function goSlide(i){if(state.policies.locked&&route!=='admin'){toast('강사 진행 중에는 다른 장으로 이동할 수 없습니다.');return;}follow=false;localSlide=Math.min(state.slides.length-1,Math.max(0,i));setRoute('slides');}
function showModal(title,body,footer=''){modalLastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="btn ghost small" data-action="close-modal" aria-label="닫기">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;$('#modal-root').querySelector('button,input,select,textarea')?.focus();}
function closeModal(){const old=modalLastFocus;$('#modal-root').innerHTML='';if(old?.isConnected)old.focus();}
function gridModal(){showModal('전체 슬라이드 · '+state.slides.length+'장',`<div class="grid-thumbs">${state.slides.map((s,i)=>`<button class="thumb-btn ${currentSlide()===i?'active':''}" data-grid-slide="${i}" ${state.policies.locked?'disabled':''}><div class="thumb-preview" aria-hidden="true">${stageMarkup(s,i,true).replace(/<button\b[^>]*>/g,'<span>').replace(/<\/button>/g,'</span>')}</div><span class="thumb-number">${String(i+1).padStart(2,'0')} · ${esc(moduleOf(s)?.title)}</span><span class="thumb-title">${esc(s.title)}</span></button>`).join('')}</div>`);$('#modal-root .modal').classList.add('grid-modal');}
function enrollmentModal(){const me=myEnrollment();showModal('수강 신청',`<p class="muted">이름은 관리자 목록에만 표시됩니다. 수업용 별명을 권장합니다.</p><form id="enroll-form" class="stack"><div class="field"><label for="enroll-name">표시 이름</label><input id="enroll-name" name="name" maxlength="30" value="${esc(me?.name||'')}" placeholder="예: 연습 수강생" required></div><p>신청 상태: <strong>${me?(me.approved?'승인 완료':'승인 대기'):'아직 신청하지 않음'}</strong></p><button type="submit" class="btn dark">${me?'신청 정보 수정':'신청하기'}</button><small class="muted">익명 인증된 수강생 계정에 저장됩니다. 이메일·문자는 발송하지 않습니다.</small></form>`);}
function confirmAction(title,text,action){showModal(title,`<p>${esc(text)}</p>`,`<button class="btn ghost" data-action="close-modal">취소</button><button class="btn danger" data-confirm="${action}">확인하고 진행</button>`);}
async function copyText(text){try{if(!navigator.clipboard?.writeText)throw Error();await Promise.race([navigator.clipboard.writeText(text),new Promise((_,r)=>setTimeout(()=>r(Error()),700))]);toast('프롬프트를 복사했습니다.');}catch(e){showModal('텍스트 복사',`<p class="muted">아래 내용을 선택해 복사하세요.</p><textarea id="copy-fallback" rows="8" readonly>${esc(text)}</textarea>`);const a=$('#copy-fallback');a.focus();a.select();try{if(document.execCommand('copy')){closeModal();toast('프롬프트를 복사했습니다.');}}catch(e){}}}
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportCourse(){const normalized=cloud.normalizeContent(state);download('my-course.json',JSON.stringify({format:'classroom-course',version:1,course:normalized.course,slides:normalized.slides},null,2),'application/json');}
function resourceText(type){if(type==='prompts')return state.slides.filter(s=>s.kind==='prompt').map(s=>s.title+'\n\n'+s.prompt).join('\n\n----------\n\n');if(type==='notes')return state.course.title+'\n수업 진행 · 총 155분\n\n1차시 00:00~00:45 첫 게임 제작\n휴식 00:45~00:55\n2차시 00:55~01:40 규칙과 재미\n휴식 01:40~01:50\n3차시 01:50~02:35 나만의 게임 완성\n\n내 게임 제목: \n게임 규칙: \n개선한 점: \n테스트 결과: \n남은 질문: \n\nAI는 선생님이 허용한 계정과 도구로 사용하고 개인정보를 입력하지 않습니다. 계정 생성·로그인·AI API 자동 연결은 제공하지 않습니다.\n';return state.course.title+'\n게임 완성 체크리스트\n\n[ ] game.html을 UTF-8로 저장, 확장자 .txt 아님\n[ ] 시작 전 점수 0점 · 남은 시간 30초\n[ ] 별 클릭마다 1점 증가\n[ ] 종료 후 추가 득점 불가\n[ ] 다시 시작하면 점수·시간 초기화\n[ ] 일시정지 후 재개하면 남은 시간 유지\n[ ] 모바일에서 별이 화면 밖으로 나가지 않음\n[ ] 키보드 Tab과 Enter로 조작 가능\n[ ] 실명·학교명·사진·계정·비밀키 미포함\n[ ] 오류를 재현하고 변경은 한 번에 하나씩 요청\n[ ] 공유 전 선생님 확인\n\n현재 강의실은 Firebase 온라인 버전입니다. 인터넷 연결과 인증이 필요합니다.\n';}
async function startTimer(minutes){await updateStore(s=>{const seconds=Math.max(1,Number(minutes)||5)*60;s.live.timerEnd=Date.now()+seconds*1000;s.live.timerPaused=seconds;});}
function tickTimers(){const seconds=state.live.timerEnd?Math.max(0,Math.ceil((state.live.timerEnd-Date.now())/1000)):state.live.timerPaused||0;const text=seconds?`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`:state.live.timerEnd?'00:00':route==='slides'&&state.slides[currentSlide()]&&['practice','break'].includes(state.slides[currentSlide()]?.kind)?String(state.slides[currentSlide()].minutes||5).padStart(2,'0')+':00':'05:00';document.querySelectorAll('#main [data-timer]').forEach(el=>{el.textContent=text;el.classList.toggle('timer-ended',!!state.live.timerEnd&&seconds===0);});}
function printSlides(){if(!state.policies.pdf){toast('현재 PDF 저장이 허용되지 않습니다.');return;}$('#print-root').innerHTML=state.slides.map((s,i)=>`<section class="print-slide">${stageMarkup(s,i,true)}</section>`).join('');window.print();}
function validateCourse(x){const fail=m=>{throw Error(m);};if(x?.format!=='classroom-course'||x.version!==1)fail('지원하는 강의 JSON 형식이 아닙니다.');const c=x.course;if(!c||!Array.isArray(c.modules)||c.modules.length<1||c.modules.length>12)fail('학습 모듈을 1~12개 넣어주세요.');['title','subtitle','instructor','date','duration','audience','description'].forEach(k=>{if(typeof c[k]!=='string'||c[k].length>2000)fail('강의 정보 항목을 확인해주세요: '+k);});const ids=c.modules.map(m=>m.id);if(new Set(ids).size!==ids.length||ids.some(id=>typeof id!=='string'||!/^[A-Za-z0-9_-]{1,80}$/.test(id)||['__proto__','constructor','prototype'].includes(id)))fail('모듈 ID가 올바르지 않습니다.');c.modules.forEach(m=>{if(typeof m.title!=='string'||typeof m.summary!=='string'||!Number.isFinite(m.minutes)||m.minutes<0)fail('모듈 내용을 확인해주세요.');});if(!Array.isArray(c.resources)||!c.resources.every(r=>typeof r.title==='string'&&typeof r.description==='string'&&['checklist','notes','prompts'].includes(r.type)))fail('자료실 형식이 잘못되었습니다.');if(!Array.isArray(c.glossary)||!c.glossary.every(g=>typeof g.term==='string'&&typeof g.definition==='string'))fail('용어집 형식을 확인해주세요.');if(!Array.isArray(x.slides)||!x.slides.length||x.slides.length>150)fail('슬라이드는 1~150장이어야 합니다.');const slideIds=new Set();x.slides.forEach((s,i)=>{if(!s.id||typeof s.id!=='string'||!/^[A-Za-z0-9_-]{1,80}$/.test(s.id)||['__proto__','constructor','prototype'].includes(s.id)||slideIds.has(s.id))fail('슬라이드 ID가 없거나 중복되었습니다.');slideIds.add(s.id);if(!ids.includes(s.module)||!['cover','cards','steps','compare','prompt','quiz','practice','break','ending'].includes(s.kind)||typeof s.title!=='string'||typeof s.subtitle!=='string')fail(`${i+1}번 슬라이드 기본 정보가 올바르지 않습니다.`);if(!Array.isArray(s.items)||s.items.length>4||s.items.some(it=>typeof it.title!=='string'||typeof it.body!=='string'))fail(`${i+1}번 슬라이드 카드 형식이 올바르지 않습니다.`);if(s.kind==='quiz'&&(!Array.isArray(s.options)||s.options.length<2||s.options.length>4||!s.options.every(o=>typeof o==='string')||!Number.isInteger(s.answer)||s.answer<0||s.answer>=s.options.length))fail('퀴즈 보기·정답을 확인해주세요.');if(s.kind==='prompt'&&typeof s.prompt!=='string')fail('프롬프트 내용을 확인해주세요.');});return true;}
function backupState(x){if(x?.format!=='classroom-backup'||x.version!==1||!x.state)throw Error('전체 백업 형식이 올바르지 않습니다.');const next=cloud.normalizeContent(x.state);validateCourse({format:'classroom-course',version:1,course:next.course,slides:next.slides});cloud.validateRestore(next);return next;}
async function importCourse(file){if(!file)return;try{if(file.size>2e6)throw Error('2MB 이하의 파일을 선택해주세요.');let x=JSON.parse(await file.text());const isBackup=x.format==='classroom-backup';let replacement;if(isBackup)replacement=backupState(x);else{x=cloud.normalizeContent(x);validateCourse(x);replacement={...defaults(),course:clone(x.course),slides:clone(x.slides)};}cloud.validateRestore(replacement);showModal(isBackup?'전체 백업을 복원할까요?':'새 강의로 교체할까요?',`<p><strong>${esc(replacement.course.title)}</strong> · ${replacement.slides.length}장</p><p>${isBackup?'강의 콘텐츠와 운영 기록을 함께 복원합니다.':'새 강의를 가져오면 기존 참여 기록은 초기화됩니다.'} 현재 상태는 먼저 전체 백업 파일로 내려받습니다.</p>`,`<button class="btn ghost" data-action="close-modal">취소</button><button class="btn dark" id="confirm-import">백업 후 ${isBackup?'복원':'가져오기'}</button>`);$('#confirm-import').onclick=safe(async()=>{download('classroom-backup-before-import.json',JSON.stringify({format:'classroom-backup',version:1,state},null,2),'application/json');await cloud.restore(replacement);state=cloud.snapshot();dirtyFields.clear();localSlide=0;closeModal();render();toast(isBackup?'전체 백업을 복원했습니다.':'새 강의 콘텐츠를 가져왔습니다.');});}catch(e){toast('가져오기 실패: '+e.message);}}

// Delegated events keep re-rendered views interactive without duplicate handlers.
document.addEventListener('click',safe(async e=>{const b=e.target.closest('button,a[data-route],label[data-action]');if(!b)return;const d=b.dataset;
 if(d.action==='teacher-login'){await cloud.login();return;}if(d.action==='teacher-logout'){await cloud.logout();return;}
 const teacherAction=d.adminTab||d.teacherStep||d.questionDone||d.questionDelete||d.reviewApprove||d.reviewDelete||d.enrollApprove||d.deleteSlide!==undefined||d.confirm||d.startPractice||['student-window','export-course','export-records','reset-records','reset-all','timer-start','timer-pause','timer-reset','add-slide'].includes(d.action);if(teacherAction&&!isTeacher()){toast('강사 인증이 필요합니다.');return;}
 if(d.route){e.preventDefault();setRoute(d.route);return;}
 if(d.adminTab){adminTab=d.adminTab;render();return;}
 if(d.partTab){participationTab=d.partTab;render();return;}
 if(d.moduleStart){const i=state.slides.findIndex(s=>s.module===d.moduleStart);goSlide(Math.max(0,i));return;}
 if(d.goSlide!==undefined){goSlide(Number(d.goSlide));return;}
 if(d.gridSlide!==undefined){closeModal();goSlide(Number(d.gridSlide));return;}
 if(d.copySlide!==undefined){copyText(state.slides[Number(d.copySlide)].prompt||'');return;}
 if(d.answerSlide!==undefined){const s=state.slides[Number(d.answerSlide)];await updateStore(x=>{x.answers[s.id]??={};x.answers[s.id][personId]=Number(d.answer);});toast('본인 응답이 서버에 저장되었습니다.');return;}
 if(d.startPractice){await startTimer(Number(d.startPractice));return;}
 if(d.teacherStep){await setTeacherSlide(teacherSlide()+Number(d.teacherStep));return;}
 if(d.questionVote){await updateStore(s=>{const q=s.questions.find(q=>q.id===d.questionVote);if(q&&!q.voters.includes(personId))q.voters.push(personId);});return;}
 if(d.questionDone){await updateStore(s=>{const q=s.questions.find(q=>q.id===d.questionDone);if(q)q.done=!q.done;});return;}
 if(d.questionDelete){await updateStore(s=>s.questions=s.questions.filter(q=>q.id!==d.questionDelete));return;}
 if(d.reviewApprove){await updateStore(s=>{const r=s.reviews.find(r=>r.id===d.reviewApprove);if(r)r.approved=!r.approved;});return;}
 if(d.reviewDelete){await updateStore(s=>s.reviews=s.reviews.filter(r=>r.id!==d.reviewDelete));return;}
 if(d.enrollApprove){await updateStore(s=>{const a=s.enrollments.find(a=>a.id===d.enrollApprove);if(a)a.approved=!a.approved;});return;}
 if(d.resource){if(!state.policies.materials){toast('자료가 비공개 상태입니다.');return;}download(`classroom-${d.resource}.txt`,resourceText(d.resource));return;}
 if(d.deleteSlide!==undefined){confirmAction('슬라이드 삭제','이 장을 삭제하면 퀴즈 응답도 함께 삭제됩니다.','delete-slide-'+d.deleteSlide);return;}
 if(d.confirm){const action=d.confirm;closeModal();if(action==='reset-all'){await cloud.reset(true);state=cloud.snapshot();localSlide=0;}else if(action==='reset-records'){await cloud.reset(false);state=cloud.snapshot();}else if(action==='export-records'){download('classroom-records.json',JSON.stringify({format:'classroom-backup',version:1,exported:new Date().toISOString(),state},null,2),'application/json');}else if(action.startsWith('delete-slide-')){const i=Number(action.replace('delete-slide-',''));await updateStore(s=>{if(s.slides.length<2)return;delete s.answers[s.slides[i].id];s.slides.splice(i,1);s.live.slide=Math.min(s.live.slide,s.slides.length-1);});localSlide=Math.min(localSlide,state.slides.length-1);}render();toast('변경 내용을 저장했습니다.');return;}
 switch(d.action){case'play-game':playGame();break;case'download-game':download('별잡기.html',window.WEBGAME_DEMO_HTML,'text/html;charset=utf-8');break;case'prev':moveSlide(-1);break;case'next':moveSlide(1);break;case'grid':gridModal();break;case'print':printSlides();break;case'fullscreen':{const el=$('#slide-stage');if(el?.requestFullscreen)el.requestFullscreen().catch(()=>toast('이 브라우저에서는 전체화면을 사용할 수 없습니다.'));else toast('이 브라우저에서는 전체화면을 지원하지 않습니다.');break;}case'close-modal':closeModal();break;case'enroll':enrollmentModal();break;case'student-window':window.open(location.href.split('#')[0]+'#slides','_blank','noopener');break;case'export-course':exportCourse();break;case'export-records':confirmAction('운영 기록 내보내기','신청 이름과 질문·후기가 포함됩니다. 파일을 공개 저장소에 올리지 마세요.','export-records');break;case'reset-records':confirmAction('참여 기록 초기화','신청·질문·후기·퀴즈 응답과 진행 상태가 삭제됩니다. 먼저 운영 기록을 백업하세요.','reset-records');break;case'reset-all':confirmAction('샘플 강의로 초기화','편집한 강의와 모든 운영 기록이 삭제됩니다. 먼저 콘텐츠와 운영 기록을 백업하세요.','reset-all');break;case'timer-start':await startTimer(Number($('#timer-minutes')?.value||5));break;case'timer-pause':await updateStore(s=>{s.live.timerPaused=s.live.timerEnd?Math.max(0,Math.ceil((s.live.timerEnd-Date.now())/1000)):s.live.timerPaused;s.live.timerEnd=0;});break;case'timer-reset':await updateStore(s=>{s.live.timerEnd=0;s.live.timerPaused=0;});break;case'add-slide':await updateStore(s=>s.slides.push({id:uid(),module:s.course.modules[0].id,kind:'cards',title:'새 슬라이드',subtitle:'여기에 핵심 내용을 적어주세요.',items:[{title:'핵심 하나',body:'한 장에는 하나의 메시지만 담습니다.'}]}));$('#edit-slide-select').value=String(state.slides.length-1);$('#slide-edit-form-slot').innerHTML=slideEditor(state.slides.length-1);break;}
}));
document.addEventListener('change',safe(async e=>{const el=e.target;if((el.dataset.policy||['teacher-jump','edit-slide-select','import-file'].includes(el.id))&&!isTeacher())return;if(el.dataset.policy){await updateStore(s=>{s.policies[el.dataset.policy]=el.checked;});return;}if(el.id==='follow-toggle'){follow=el.checked;if(follow||state.policies.locked)localSlide=teacherSlide();render();return;}if(el.id==='teacher-jump'){await setTeacherSlide(Number(el.value));return;}if(el.id==='edit-slide-select'){$('#slide-edit-form-slot').innerHTML=slideEditor(Number(el.value));return;}if(el.id==='import-file')await importCourse(el.files[0]);}));
document.addEventListener('submit',safe(async e=>{const f=e.target;e.preventDefault();const fd=new FormData(f);const submittedDrafts=new Map([...dirtyFields].filter(([key])=>key.startsWith(f.id+':')).map(([key,v])=>[key,v.revision]));if(['course-form','slide-form'].includes(f.id)&&!isTeacher())return;
 if(f.id==='question-form'){const text=String(fd.get('text')).trim();if(!text)return;if(!state.policies.questions){toast('질문 접수가 닫혀 있습니다.');return;}await updateStore(s=>s.questions.push({id:uid(),person:personId,text,created:Date.now(),done:false,voters:[]}));toast('질문을 등록했습니다.');}
 else if(f.id==='review-form'){const text=String(fd.get('text')).trim();if(!text)return;if(!state.policies.reviews){toast('후기 접수가 닫혀 있습니다.');return;}const rating=Math.max(1,Math.min(5,Number(fd.get('rating'))||5));await updateStore(s=>{const old=s.reviews.find(r=>r.person===personId);if(old){Object.assign(old,{text,rating,approved:false,created:Date.now()});}else s.reviews.push({id:uid(),person:personId,text,rating,approved:false,created:Date.now()});});toast('후기를 저장했습니다. 승인 전에는 비공개입니다.');}
 else if(f.id==='enroll-form'){const name=String(fd.get('name')).trim();if(!name)return;await updateStore(s=>{const old=s.enrollments.find(e=>e.person===personId);if(old)Object.assign(old,{name,approved:false,created:Date.now()});else s.enrollments.push({id:uid(),person:personId,name,approved:false,created:Date.now()});});closeModal();toast('신청했습니다. 강사 승인을 기다려주세요.');}
 else if(f.id==='course-form'){await updateStore(s=>{['title','subtitle','instructor','date','duration','audience','description'].forEach(k=>s.course[k]=String(fd.get(k)).trim());});toast('강의 정보를 저장했습니다.');}
 else if(f.id==='slide-form'){const i=Number(f.dataset.index);const items=String(fd.get('items')).split('\n').filter(x=>x.trim()).map(line=>{const [title,...rest]=line.split('|');return{title:title.trim(),body:rest.join('|').trim()};});if(items.length>4){toast('카드는 최대 4개입니다.');return;}if(state.slides[i].kind==='quiz'){const options=String(fd.get('options')).split('\n').map(x=>x.trim()).filter(Boolean);const answer=Number(fd.get('answer'))-1;if(options.length<2||options.length>4||answer<0||answer>=options.length){toast('보기 2~4개와 올바른 정답 번호를 입력하세요.');return;}}
 await updateStore(s=>{const slide=s.slides[i];Object.assign(slide,{title:String(fd.get('title')).trim(),subtitle:String(fd.get('subtitle')).trim(),module:String(fd.get('module')),items});if(slide.kind==='prompt')slide.prompt=String(fd.get('prompt'));if(['practice','break'].includes(slide.kind))slide.minutes=Number(fd.get('minutes'));if(slide.kind==='quiz'){slide.options=String(fd.get('options')).split('\n').map(x=>x.trim()).filter(Boolean);slide.answer=Number(fd.get('answer'))-1;delete s.answers[slide.id];}});$('#edit-slide-select').value=String(i);$('#slide-edit-form-slot').innerHTML=slideEditor(i);toast('슬라이드와 관리자 목록을 함께 갱신했습니다.');}
for(const [key,revision]of submittedDrafts)if(dirtyFields.get(key)?.revision===revision)dirtyFields.delete(key);render();
}));
window.addEventListener('hashchange',()=>{const r=location.hash.replace('#','').split('/')[0];route=['home','slides','participate','resources','admin'].includes(r)?r:'home';render();window.scrollTo({top:0});});
function receiveRemote(next){captureDrafts();state=next;if(follow||state.policies.locked)localSlide=teacherSlide();render();}
if(cloud){cloud.on('state',receiveRemote);cloud.on('status',s=>{const changed=cloudStatus.teacher!==s.teacher||personId!==(s.uid||'');cloudStatus=s;personId=s.uid||'';if(changed)dirtyFields.clear();renderCloudStatus();if(changed)render();});cloud.on('error',text=>toast(text));}
document.addEventListener('keydown',safe(async e=>{const modal=$('#modal-root .modal');if(modal){if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const f=[...modal.querySelectorAll('button:not([disabled]),input,select,textarea,a[href]')].filter(x=>!x.hidden);if(f.length){const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}return;}if(e.target.matches('input,textarea,select')||e.ctrlKey||e.metaKey||e.altKey)return;if(route==='slides'){if(e.key==='ArrowRight'){e.preventDefault();moveSlide(1);}if(e.key==='ArrowLeft'){e.preventDefault();moveSlide(-1);}if(e.key.toLowerCase()==='g')gridModal();if(e.key.toLowerCase()==='p')printSlides();}if(isTeacher()&&route==='admin'&&adminTab==='control'){if(e.key==='ArrowRight')await setTeacherSlide(teacherSlide()+1);if(e.key==='ArrowLeft')await setTeacherSlide(teacherSlide()-1);}}));
// A running timer is calculated from an absolute end time, not decremented ticks.
setInterval(tickTimers,250);
render();
if(cloud)cloud.start(defaults());else toast('온라인 연결을 불러오지 못했습니다. 슬라이드와 게임만 사용할 수 있습니다.');
})();
